/**
 * Explorable widgets — the manipulate-to-learn step system (Project Brilliant, Phase 1.1).
 *
 * Contract every widget follows:
 *   1. MANIPULATE — the learner adjusts something (slider, drag, toggle).
 *   2. CONSEQUENCE — a linked visualization updates live with every adjustment.
 *   3. INSIGHT — once the interaction goal is met, the insight text reveals.
 *   4. CHECK (optional) — a one-question comprehension check gates completion.
 *
 * Widgets are pure presentational components driven entirely by `ExplorableStepData`
 * so a single widget serves many lessons via different params.
 */

export interface ExplorableCheck {
  question: string;
  options: string[];
  /** Index into options */
  correct: number;
  explanationCorrect: string;
  explanationWrong: string;
}

export interface ExplorableStepData {
  type: 'explorable';
  /** Registry key, e.g. 'compoundGrowthLab' */
  widget: string;
  title: string;
  /** What the learner is asked to do/discover, e.g. "Drag the rate — find what doubles the outcome." */
  prompt: string;
  /**
   * Widget-specific configuration; each widget documents its own params shape.
   *
   * Convention — predict-first (the bet flow): widgets that support it read
   * `params.predict` as `{ question: string; options: string[] }` via the
   * `predictParam()` helper in `_shared.tsx`. When present, the hero starts
   * dimmed and controls stay disabled until the learner commits to an option;
   * no right/wrong feedback is given at bet time — the reveal settles it.
   */
  params?: Record<string, unknown>;
  /** Revealed after the interaction goal is met — the "aha" in words. */
  insight: string;
  /** Optional comprehension check; if present, completion (correct=true) requires answering. */
  check?: ExplorableCheck;
}

/**
 * Implementation rules (enforced by review, mirrors MOTION_SYSTEM_SPEC.md):
 * - Consequence viz must update on EVERY manipulation frame (no "submit to see result").
 * - Animate transform/opacity only in hot paths; charts may redraw data.
 * - Respect prefers-reduced-motion via framer-motion's useReducedMotion.
 * - Touch targets >= 44px; layout must work at 360px width.
 * - Use design tokens (hsl(var(--primary)) etc.) — no hardcoded hex except chart series
 *   colors taken from the shared palette below.
 */
export const EXPLORABLE_CHART_COLORS = {
  primary: '#A451E6',
  // Deliberately NOT in the orchid family: two-series charts need a second
  // hue you can tell apart at a glance (supply vs demand, you vs benchmark).
  accent: '#2DD4BF',
  positive: '#10B981',
  negative: '#EF4444',
  muted: '#64748B',
} as const;
